class Solution:
    def maxDifference(self, s: str) -> int:
        # Count the frequency of each character in the string
        counts = {}
        for char in s:
            counts[char] = counts.get(char, 0) + 1

        # Initialize variables to track the maximum odd frequency and minimum even frequency
        # max_odd_freq should be at least 0 (or -1 as a sentinel)
        max_odd_freq = -1
        # min_even_freq should be initialized to a value larger than any possible frequency (length of s)
        min_even_freq = float('inf')

        # Iterate through the frequencies of all characters
        for count in counts.values():
            if count % 2 == 1:
                # If the frequency is odd, update the maximum odd frequency found so far
                if count > max_odd_freq:
                    max_odd_freq = count
            else:
                # If the frequency is even, update the minimum even frequency found so far
                if count < min_even_freq:
                    min_even_freq = count

        # The maximum difference is the maximum odd frequency minus the minimum even frequency
        return max_odd_freq - min_even_freq
