import sys

def main():
    # Read all input from standard input
    # split() handles newlines and spaces automatically
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        # Read N
        N = int(next(iterator))
    except StopIteration:
        return

    # Read P_1 to P_N
    P = []
    for _ in range(N):
        try:
            val = int(next(iterator))
            P.append(val)
        except StopIteration:
            break

    # Store scores with their original indices (0-based)
    # This helps us track which person corresponds to which score
    people = []
    for i in range(N):
        people.append((P[i], i))

    # Array to store the rank for each person index (0 to N-1)
    ranks = [0] * N

    # Set of indices of people whose ranks are not yet determined
    undetermined = set(range(N))

    # Current rank counter
    r = 1

    # Repeat until all ranks are determined
    while undetermined:
        # Find the maximum score among undetermined people
        max_score = -1
        for score, idx in people:
            if idx in undetermined:
                if score > max_score:
                    max_score = score

        # Count how many people have this maximum score among undetermined
        count = 0
        for score, idx in people:
            if idx in undetermined and score == max_score:
                count += 1

        # Assign the current rank 'r' to all people with the maximum score
        for score, idx in people:
            if idx in undetermined and score == max_score:
                ranks[idx] = r
                undetermined.remove(idx)

        # Update r for the next round
        r += count

    # Print the rank for each person (1 to N)
    for rank in ranks:
        print(rank)

if __name__ == '__main__':
    main()
