class Solution:
    def maxDifference(self, s: str) -> int:
        # Count the frequency of each character
        freq = {}
        for char in s:
            freq[char] = freq.get(char, 0) + 1

        # Initialize variables to track the maximum odd frequency and minimum even frequency
        max_odd = 0
        min_even = float('inf')

        # Iterate over the frequencies to find the required values
        for count in freq.values():
            if count % 2 == 1:
                # Update max_odd if current count is odd and larger
                max_odd = max(max_odd, count)
            else:
                # Update min_even if current count is even and smaller
                min_even = min(min_even, count)

        # Return the difference between the maximum odd frequency and minimum even frequency
        return max_odd - min_even
